import{_ as o,a0 as p,w as d,s as r,I as e,x as a,a1 as t,A as l,ao as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"你所不了解的 Bash：关于 Bash 数组的介绍 | LCTT x X-CMD","titleTemplate":false,"description":"你所不了解的 Bash：关于 Bash 数组的介绍 | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"你所不了解的 Bash：关于 Bash 数组的介绍 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"你所不了解的 Bash：关于 Bash 数组的介绍 | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20180531 You don-t know Bash- An introduction to Bash arrays","title":"你所不了解的 Bash：关于 Bash 数组的介绍","tag":"201807","desc":""},"relativePath":"201807/20180531 You don-t know Bash- An introduction to Bash arrays.md","filePath":"[post].md"}'),h={name:"201807/20180531 You don-t know Bash- An introduction to Bash arrays.md"};function u(c,s,g,b,f,k){const n=p("Link");return d(),r("div",null,[s[36]||(s[36]=e("h1",{id:"你所不了解的-bash-关于-bash-数组的介绍",tabindex:"-1"},[a("你所不了解的 Bash：关于 Bash 数组的介绍 "),e("a",{class:"header-anchor",href:"#你所不了解的-bash-关于-bash-数组的介绍","aria-label":"Permalink to “你所不了解的 Bash：关于 Bash 数组的介绍”"},"​")],-1)),s[37]||(s[37]=e("blockquote",null,[e("p",null,"进入这个古怪而神奇的 Bash 数组的世界。")],-1)),s[38]||(s[38]=e("p",null,[e("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/programming-code-keyboard-laptop.png?itok=pGfEfu2S",alt:""})],-1)),e("p",null,[s[1]||(s[1]=a("尽管软件工程师常常使用命令行来进行各种开发，但命令行中的数组似乎总是一个模糊的东西（虽然不像正则操作符 ",-1)),s[2]||(s[2]=e("code",null,"=~",-1)),s[3]||(s[3]=a(" 那么复杂隐晦）。除开隐晦和有疑问的语法，",-1)),t(n,{href:"https://opensource.com/article/17/7/bash-prompt-tips-and-tricks"},{default:l(()=>[...s[0]||(s[0]=[a("Bash",-1)])]),_:1}),s[4]||(s[4]=a(" 数组其实是非常有用的。",-1))]),s[39]||(s[39]=i(`<h3 id="稍等-这是为什么" tabindex="-1">稍等，这是为什么？ <a class="header-anchor" href="#稍等-这是为什么" aria-label="Permalink to “稍等，这是为什么？”">​</a></h3><p>写 Bash 相关的东西很难，但如果是写一篇像手册那样注重怪异语法的文章，就会非常简单。不过请放心，这篇文章的目的就是让你不用去读该死的使用手册。</p><h4 id="真实-通常是有用的-示例" tabindex="-1">真实（通常是有用的）示例 <a class="header-anchor" href="#真实-通常是有用的-示例" aria-label="Permalink to “真实（通常是有用的）示例”">​</a></h4><p>为了这个目的，想象一下真实世界的场景以及 Bash 是怎么帮忙的：你正在公司里面主导一个新工作，评估并优化内部数据管线的运行时间。首先，你要做个参数扫描分析来评估管线使用线程的状况。简单起见，我们把这个管道当作一个编译好的 C++ 黑盒子，这里面我们能够调整的唯一的参数是用于处理数据的线程数量：<code>./pipeline --threads 4</code>。</p><h3 id="基础" tabindex="-1">基础 <a class="header-anchor" href="#基础" aria-label="Permalink to “基础”">​</a></h3><p>我们首先要做的事是定义一个数组，用来容纳我们想要测试的 <code>--threads</code> 参数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>allThreads=(1 2 4 8 16 32 64 128)</span></span></code></pre></div><p>本例中，所有元素都是数字，但参数并不一定是数字，Bash 中的数组可以容纳数字和字符串，比如 <code>myArray=(1 2 &quot;three&quot; 4 &quot;five&quot;)</code> 就是个有效的表达式。就像 Bash 中其它的变量一样，确保赋值符号两边没有空格。否则 Bash 将会把变量名当作程序来执行，把 <code>=</code> 当作程序的第一个参数。</p><p>现在我们初始化了数组，让我们解析它其中的一些元素。仅仅输入 <code>echo $allThreads</code> ，你能发现，它只会输出第一个元素。</p><p>要理解这个产生的原因，需要回到上一步，回顾我们一般是怎么在 Bash 中输出变量。考虑以下场景：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type=&quot;article&quot;</span></span>
<span class="line"><span>echo &quot;Found 42 $type&quot;</span></span></code></pre></div>`,11)),e("p",null,[s[6]||(s[6]=i("假如我们得到的变量 <code>$type</code> 是一个单词，我们想要添加在句子结尾一个 <code>s</code>。我们无法直接把 <code>s</code> 加到 <code>$type</code> 里面，因为这会把它变成另一个变量，<code>$types</code>。尽管我们可以利用像 <code>echo &quot;Found 42 &quot;$type&quot;s&quot;</code> 这样的代码形变，但解决这个问题的最好方法是用一个花括号：<code>echo &quot;Found 42 ${type}s&quot;</code>，这让我们能够告诉 Bash 变量名的起止位置（有趣的是，JavaScript/ES6 在 ",15)),t(n,{href:"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Template_literals"},{default:l(()=>[...s[5]||(s[5]=[a("template literals",-1)])]),_:1}),s[7]||(s[7]=a(" 中注入变量和表达式的语法和这里是一样的）",-1))]),s[40]||(s[40]=i(`<p>事实上，尽管 Bash 变量一般不用花括号，但在数组中需要用到花括号。这反而允许我们指定要访问的索引，例如 <code>echo \${allThreads[1]}</code> 返回的是数组中的第二个元素。如果不写花括号，比如 <code>echo $allThreads[1]</code>，会导致 Bash 把 <code>[1]</code> 当作字符串然后输出。</p><p>是的，Bash 数组的语法很怪，但是至少他们是从 0 开始索引的，不像有些语言（说的就是你，<code>R</code> 语言）。</p><h3 id="遍历数组" tabindex="-1">遍历数组 <a class="header-anchor" href="#遍历数组" aria-label="Permalink to “遍历数组”">​</a></h3><p>上面的例子中我们直接用整数作为数组的索引，我们现在考虑两种其他情况：第一，如果想要数组中的第 <code>$i</code> 个元素，这里 <code>$i</code> 是一个代表索引的变量，我们可以这样 <code>echo \${allThreads[$i]}</code> 解析这个元素。第二，要输出一个数组的所有元素，我们把数字索引换成 <code>@</code> 符号（你可以把 <code>@</code> 当作表示 <code>all</code> 的符号）：<code>echo \${allThreads[@]}</code>。</p><h4 id="遍历数组元素" tabindex="-1">遍历数组元素 <a class="header-anchor" href="#遍历数组元素" aria-label="Permalink to “遍历数组元素”">​</a></h4><p>记住上面讲过的，我们遍历 <code>$allThreads</code> 数组，把每个值当作 <code>--threads</code> 参数启动管线：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for t in \${allThreads[@]}; do</span></span>
<span class="line"><span>  ./pipeline --threads $t</span></span>
<span class="line"><span>done</span></span></code></pre></div><h4 id="遍历数组索引" tabindex="-1">遍历数组索引 <a class="header-anchor" href="#遍历数组索引" aria-label="Permalink to “遍历数组索引”">​</a></h4><p>接下来，考虑一个稍稍不同的方法。不遍历所有的数组元素，我们可以遍历所有的索引：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for i in \${!allThreads[@]}; do</span></span>
<span class="line"><span>  ./pipeline --threads \${allThreads[$i]}</span></span>
<span class="line"><span>done</span></span></code></pre></div><p>一步一步看：如之前所见，<code>\${allThreads[@]}</code> 表示数组中的所有元素。前面加了个感叹号，变成 <code>\${!allThreads[@]}</code>，这会返回数组索引列表（这里是 0 到 7）。换句话说。<code>for</code> 循环就遍历所有的索引 <code>$i</code> 并从 <code>$allThreads</code> 中读取第 <code>$i</code> 个元素，当作 <code>--threads</code> 选项的参数。</p><p>这看上去很辣眼睛，你可能奇怪为什么我要一开始就讲这个。这是因为有时候在循环中需要同时获得索引和对应的值，例如，如果你想要忽视数组中的第一个元素，使用索引可以避免额外创建在循环中累加的变量。</p><h3 id="填充数组" tabindex="-1">填充数组 <a class="header-anchor" href="#填充数组" aria-label="Permalink to “填充数组”">​</a></h3><p>到目前为止，我们已经能够用给定的 <code>--threads</code> 选项启动管线了。现在假设按秒计时的运行时间输出到管线。我们想要捕捉每个迭代的输出，然后把它保存在另一个数组中，因此我们最终可以随心所欲的操作它。</p><h4 id="一些有用的语法" tabindex="-1">一些有用的语法 <a class="header-anchor" href="#一些有用的语法" aria-label="Permalink to “一些有用的语法”">​</a></h4><p>在深入代码前，我们要多介绍一些语法。首先，我们要能解析 Bash 命令的输出。用这个语法可以做到：<code>output=$( ./my_script.sh )</code>，这会把命令的输出存储到变量 <code>$output</code> 中。</p><p>我们需要的第二个语法是如何把我们刚刚解析的值添加到数组中。完成这个任务的语法看起来很熟悉：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>myArray+=( &quot;newElement1&quot; &quot;newElement2&quot; )</span></span></code></pre></div><h4 id="参数扫描" tabindex="-1">参数扫描 <a class="header-anchor" href="#参数扫描" aria-label="Permalink to “参数扫描”">​</a></h4><p>万事具备，执行参数扫描的脚步如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>allThreads=(1 2 4 8 16 32 64 128)</span></span>
<span class="line"><span>allRuntimes=()</span></span>
<span class="line"><span>for t in \${allThreads[@]}; do</span></span>
<span class="line"><span>  runtime=$(./pipeline --threads $t)</span></span>
<span class="line"><span>  allRuntimes+=( $runtime )</span></span>
<span class="line"><span>done</span></span></code></pre></div><p>就是这个了！</p><h3 id="还有什么能做的" tabindex="-1">还有什么能做的？ <a class="header-anchor" href="#还有什么能做的" aria-label="Permalink to “还有什么能做的？”">​</a></h3><p>这篇文章中，我们讲过使用数组进行参数扫描的场景。我敢保证有很多理由要使用 Bash 数组，这里就有两个例子：</p><h4 id="日志警告" tabindex="-1">日志警告 <a class="header-anchor" href="#日志警告" aria-label="Permalink to “日志警告”">​</a></h4><p>本场景中，把应用分成几个模块，每一个都有它自己的日志文件。我们可以编写一个 cron 任务脚本，当某个模块中出现问题标志时向特定的人发送邮件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 日志列表，发生问题时应该通知的人</span></span>
<span class="line"><span>logPaths=(&quot;api.log&quot; &quot;auth.log&quot; &quot;jenkins.log&quot; &quot;data.log&quot;)</span></span>
<span class="line"><span>logEmails=(&quot;jay@email&quot; &quot;emma@email&quot; &quot;jon@email&quot; &quot;sophia@email&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 在每个日志中查找问题标志</span></span>
<span class="line"><span>for i in \${!logPaths[@]};</span></span>
<span class="line"><span>do</span></span>
<span class="line"><span>  log=\${logPaths[$i]}</span></span>
<span class="line"><span>  stakeholder=\${logEmails[$i]}</span></span>
<span class="line"><span>  numErrors=$( tail -n 100 &quot;$log&quot; | grep &quot;ERROR&quot; | wc -l )</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  # 如果近期发现超过 5 个错误，就警告负责人</span></span>
<span class="line"><span>  if [[ &quot;$numErrors&quot; -gt 5 ]];</span></span>
<span class="line"><span>  then</span></span>
<span class="line"><span>    emailRecipient=&quot;$stakeholder&quot;</span></span>
<span class="line"><span>    emailSubject=&quot;WARNING: \${log} showing unusual levels of errors&quot;</span></span>
<span class="line"><span>    emailBody=&quot;\${numErrors} errors found in log \${log}&quot;</span></span>
<span class="line"><span>    echo &quot;$emailBody&quot; | mailx -s &quot;$emailSubject&quot; &quot;$emailRecipient&quot;</span></span>
<span class="line"><span>  fi</span></span>
<span class="line"><span>done</span></span></code></pre></div><h4 id="api-查询" tabindex="-1">API 查询 <a class="header-anchor" href="#api-查询" aria-label="Permalink to “API 查询”">​</a></h4><p>如果你想要生成一些分析数据，分析你的 Medium 帖子中用户评论最多的。由于我们无法直接访问数据库，SQL 不在我们考虑范围，但我们可以用 API！</p>`,29)),e("p",null,[s[9]||(s[9]=a("为了避免陷入关于 API 授权和令牌的冗长讨论，我们将会使用 ",-1)),t(n,{href:"https://github.com/typicode/jsonplaceholder"},{default:l(()=>[...s[8]||(s[8]=[a("JSONPlaceholder",-1)])]),_:1}),s[10]||(s[10]=a("，这是一个面向公众的测试服务 API。一旦我们查询每个帖子，解析出每个评论者的邮箱，我们就可以把这些邮箱添加到我们的结果数组里：",-1))]),s[41]||(s[41]=i(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>endpoint=&quot;https://jsonplaceholder.typicode.com/comments&quot;</span></span>
<span class="line"><span>allEmails=()</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 查询前 10 个帖子</span></span>
<span class="line"><span>for postId in {1..10};</span></span>
<span class="line"><span>do</span></span>
<span class="line"><span>  # 执行 API 调用，获取该帖子评论者的邮箱</span></span>
<span class="line"><span>  response=$(curl &quot;\${endpoint}?postId=\${postId}&quot;)</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  # 使用 jq 把 JSON 响应解析成数组</span></span>
<span class="line"><span>  allEmails+=( $( jq &#39;.[].email&#39; &lt;&lt;&lt; &quot;$response&quot; ) )</span></span>
<span class="line"><span>done</span></span></code></pre></div>`,1)),e("p",null,[s[12]||(s[12]=a("注意这里我是用 ",-1)),t(n,{href:"https://stedolan.github.io/jq/"},{default:l(()=>[...s[11]||(s[11]=[a("jq 工具",-1)])]),_:1}),s[13]||(s[13]=a(" 从命令行里解析 JSON 数据。关于 ",-1)),s[14]||(s[14]=e("code",null,"jq",-1)),s[15]||(s[15]=a(" 的语法超出了本文的范围，但我强烈建议你了解它。",-1))]),s[42]||(s[42]=i(`<p>你可能已经想到，使用 Bash 数组在数不胜数的场景中很有帮助，我希望这篇文章中的示例可以给你思维的启发。如果你从自己的工作中找到其它的例子想要分享出来，请在帖子下方评论。</p><h3 id="请等等-还有很多东西" tabindex="-1">请等等，还有很多东西！ <a class="header-anchor" href="#请等等-还有很多东西" aria-label="Permalink to “请等等，还有很多东西！”">​</a></h3><p>由于我们在本文讲了很多数组语法，这里是关于我们讲到内容的总结，包含一些还没讲到的高级技巧：</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">语法</th><th style="text-align:left;">效果</th></tr></thead><tbody><tr><td style="text-align:left;"><code>arr=()</code></td><td style="text-align:left;">创建一个空数组</td></tr><tr><td style="text-align:left;"><code>arr=(1 2 3)</code></td><td style="text-align:left;">初始化数组</td></tr><tr><td style="text-align:left;"><code>\${arr[2]}</code></td><td style="text-align:left;">取得第三个元素</td></tr><tr><td style="text-align:left;"><code>\${arr[@]}</code></td><td style="text-align:left;">取得所有元素</td></tr><tr><td style="text-align:left;"><code>\${!arr[@]}</code></td><td style="text-align:left;">取得数组索引</td></tr><tr><td style="text-align:left;"><code>\${#arr[@]}</code></td><td style="text-align:left;">计算数组长度</td></tr><tr><td style="text-align:left;"><code>arr[0]=3</code></td><td style="text-align:left;">覆盖第 1 个元素</td></tr><tr><td style="text-align:left;"><code>arr+=(4)</code></td><td style="text-align:left;">添加值</td></tr><tr><td style="text-align:left;"><code>str=$(ls)</code></td><td style="text-align:left;">把 <code>ls</code> 输出保存到字符串</td></tr><tr><td style="text-align:left;"><code>arr=( $(ls) )</code></td><td style="text-align:left;">把 <code>ls</code> 输出的文件保存到数组里</td></tr><tr><td style="text-align:left;"><code>\${arr[@]:s:n}</code></td><td style="text-align:left;">取得从索引 <code>s</code> 开始的 <code>n</code> 个元素</td></tr></tbody></table></div><h3 id="最后一点思考" tabindex="-1">最后一点思考 <a class="header-anchor" href="#最后一点思考" aria-label="Permalink to “最后一点思考”">​</a></h3><p>正如我们所见，Bash 数组的语法很奇怪，但我希望这篇文章让你相信它们很有用。只要你理解了这些语法，你会发现以后会经常使用 Bash 数组。</p><h4 id="bash-还是-python" tabindex="-1">Bash 还是 Python？ <a class="header-anchor" href="#bash-还是-python" aria-label="Permalink to “Bash 还是 Python？”">​</a></h4><p>问题来了：什么时候该用 Bash 数组而不是其他的脚本语法，比如 Python？</p><p>对我而言，完全取决于需求——如果你可以只需要调用命令行工具就能立马解决问题，你也可以用 Bash。但有些时候，当你的脚本属于一个更大的 Python 项目时，你也可以用 Python。</p><p>比如，我们可以用 Python 来实现参数扫描，但我们只用编写一个 Bash 的包装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import subprocess</span></span>
<span class="line"><span></span></span>
<span class="line"><span>all_threads = [1, 2, 4, 8, 16, 32, 64, 128]</span></span>
<span class="line"><span>all_runtimes = []</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 用不同的线程数字启动管线</span></span>
<span class="line"><span>for t in all_threads:</span></span>
<span class="line"><span>  cmd = &#39;./pipeline --threads {}&#39;.format(t)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  # 使用子线程模块获得返回的输出</span></span>
<span class="line"><span>  p = subprocess.Popen(cmd, stdout=subprocess.PIPE, shell=True)</span></span>
<span class="line"><span>  output = p.communicate()[0]</span></span>
<span class="line"><span>  all_runtimes.append(output)</span></span></code></pre></div><p>由于本例中没法避免使用命令行，所以可以优先使用 Bash。</p><h4 id="羞耻的宣传时间" tabindex="-1">羞耻的宣传时间 <a class="header-anchor" href="#羞耻的宣传时间" aria-label="Permalink to “羞耻的宣传时间”">​</a></h4>`,13)),e("p",null,[s[18]||(s[18]=a("如果你喜欢这篇文章，这里还有很多类似的文章！ ",-1)),t(n,{href:"https://conferences.oreilly.com/oscon/oscon-or"},{default:l(()=>[...s[16]||(s[16]=[a("在此注册，加入 OSCON",-1)])]),_:1}),s[19]||(s[19]=a("，2018 年 7 月 17 号我会在这做一个主题为 ",-1)),t(n,{href:"https://conferences.oreilly.com/oscon/oscon-or/public/schedule/detail/67166"},{default:l(()=>[...s[17]||(s[17]=[a("你所不了解的 Bash",-1)])]),_:1}),s[20]||(s[20]=a(" 的在线编码研讨会。没有幻灯片，不需要门票，只有你和我在命令行里面敲代码，探索 Bash 中的奇妙世界。",-1))]),s[43]||(s[43]=e("p",null,"本文章由 [Medium] 首发，再发布时已获得授权。",-1)),s[44]||(s[44]=e("hr",null,null,-1)),e("p",null,[s[22]||(s[22]=a("via: ",-1)),t(n,{href:"https://opensource.com/article/18/5/you-dont-know-bash-intro-bash-arrays"},{default:l(()=>[...s[21]||(s[21]=[a("https://opensource.com/article/18/5/you-dont-know-bash-intro-bash-arrays",-1)])]),_:1})]),e("p",null,[s[27]||(s[27]=a("作者：",-1)),t(n,{href:"https://opensource.com/users/robertaboukhalil"},{default:l(()=>[...s[23]||(s[23]=[a("Robert Aboukhalil",-1)])]),_:1}),s[28]||(s[28]=a(" 选题：",-1)),t(n,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[24]||(s[24]=[a("lujun9972",-1)])]),_:1}),s[29]||(s[29]=a(" 译者：",-1)),t(n,{href:"https://github.com/BriFuture"},{default:l(()=>[...s[25]||(s[25]=[a("BriFuture",-1)])]),_:1}),s[30]||(s[30]=a(" 校对：",-1)),t(n,{href:"https://github.com/wxy"},{default:l(()=>[...s[26]||(s[26]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[33]||(s[33]=a("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[31]||(s[31]=[a("LCTT",-1)])]),_:1}),s[34]||(s[34]=a(" 原创编译，",-1)),t(n,{href:"https://linux.cn/"},{default:l(()=>[...s[32]||(s[32]=[a("Linux中国",-1)])]),_:1}),s[35]||(s[35]=a(" 荣誉推出",-1))])])}const q=o(h,[["render",u]]);export{T as __pageData,q as default};
